import 'package:cloud_firestore/cloud_firestore.dart';
class MessageReactionModel { const MessageReactionModel({required this.id,required this.userId,required this.emoji,required this.createdAt}); final String id,userId,emoji; final DateTime createdAt; factory MessageReactionModel.fromFirestore(DocumentSnapshot<Map<String,dynamic>> doc)=>MessageReactionModel(id:doc.id,userId:doc.data()['userId'] as String? ?? '',emoji:doc.data()['emoji'] as String? ?? '',createdAt:(doc.data()['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now()); Map<String,Object> toMap()=>{'userId':userId,'emoji':emoji,'createdAt':Timestamp.fromDate(createdAt)}; }
